WITH cleaned AS (SELECT *, COALESCE(amount, 0) AS amount_filled, CAST(paid_at AS DATE) AS paid_at_day FROM payments WHERE paid_at > TO_DATE('2023-08-01') AND method IS DISTINCT FROM 'card'), scored AS (SELECT id, order_id, paid_at, paid_at_day, MIN(amount_filled) OVER (PARTITION BY status ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_amount_filled, AVG(amount_filled) OVER (PARTITION BY status ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_amount_filled, MAX(amount_filled) OVER (PARTITION BY status ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_amount_filled FROM cleaned WHERE method != 'bank_transfer'), scored_payments AS (SELECT id, paid_at, running_max_amount_filled, CUME_DIST() OVER (PARTITION BY order_id ORDER BY running_min_amount_filled NULLS FIRST) AS running_min_amount_filled_cume_dist, COUNT(running_max_amount_filled) OVER (PARTITION BY order_id ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS running_max_amount_filled_count_30d FROM scored), filtered AS (SELECT *, running_min_amount_filled_cume_dist * running_max_amount_filled_count_30d AS running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d, running_min_amount_filled_cume_dist * running_max_amount_filled AS running_min_amount_filled_cume_dist_times_running_max_amount_filled FROM scored_payments WHERE paid_at > DATE '2023-06-15'), scored_payments_2 AS (SELECT *, SUM(running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d) OVER w_recent AS running_sum_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d, AVG(running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d) OVER w_recent AS running_avg_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d, MIN(running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d) OVER w_recent AS running_min_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d, SUM(running_min_amount_filled_cume_dist) OVER w_recent AS cumulative_running_min_amount_filled_cume_dist FROM filtered WINDOW w_recent AS (ORDER BY running_max_amount_filled_count_30d, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), with_windows AS (SELECT id, running_max_amount_filled, running_max_amount_filled_count_30d, running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d, running_min_amount_filled_cume_dist_times_running_max_amount_filled, running_avg_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d, cumulative_running_min_amount_filled_cume_dist, SUM(running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d) OVER (ORDER BY running_min_amount_filled_cume_dist_times_running_max_amount_filled, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d, LAG(running_min_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d, 1) OVER (ORDER BY running_max_amount_filled, id) AS prev_running_min_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d, COUNT(running_min_amount_filled_cume_dist) OVER (ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS running_min_amount_filled_cume_dist_count_30d FROM scored_payments_2), enriched AS (SELECT *, CUME_DIST() OVER (ORDER BY running_avg_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d) AS running_avg_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d_cume_dist, CUME_DIST() OVER (ORDER BY cumulative_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d DESC NULLS LAST) AS cumulative_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d_cume_dist, ROW_NUMBER() OVER (ORDER BY running_min_amount_filled_cume_dist_times_running_max_amount_filled, id) AS row_seq FROM with_windows) SELECT CASE WHEN running_avg_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d >= 67 THEN 'LARGE' ELSE 'SMALL' END AS running_avg_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d_tier, CASE WHEN cumulative_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d_cume_dist >= 0.75 THEN 'LARGE' ELSE 'SMALL' END AS cumulative_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d_cume_dist_tier, COUNT(DISTINCT id) AS distinct_ids, APPROX_PERCENTILE(row_seq, 0.95) AS row_seq_p95, COUNT(DISTINCT id) AS distinct_ids_2, GROUPING_ID() AS grouping_id FROM enriched GROUP BY GROUPING SETS ((CASE WHEN running_avg_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d >= 67 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN cumulative_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d_cume_dist >= 0.75 THEN 'LARGE' ELSE 'SMALL' END), (CASE WHEN running_avg_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d >= 67 THEN 'LARGE' ELSE 'SMALL' END), ()) HAVING COUNT(DISTINCT id) > 1 ORDER BY cumulative_running_min_amount_filled_cume_dist_times_running_max_amount_filled_count_30d_cume_dist_tier DESC NULLS LAST;
